class Solution {
public:
    bool validSquare(vector<int>& p1, vector<int>& p2, vector<int>& p3, vector<int>& p4) {
        vector<vector<int>> pts = {p1, p2, p3, p4};
        auto distSq = [](const vector<int>& a, const vector<int>& b) {
            return (a[0] - b[0]) * (a[0] - b[0]) + (a[1] - b[1]) * (a[1] - b[1]);
        };
        vector<int> dists;
        for (int i = 0; i < 4; i++) {
            for (int j = i + 1; j < 4; j++) {
                dists.push_back(distSq(pts[i], pts[j]));
            }
        }
        sort(dists.begin(), dists.end());
        return dists[0] > 0 &&
               dists[0] == dists[1] && dists[1] == dists[2] && dists[2] == dists[3] &&
               dists[4] == dists[5] && dists[4] == 2 * dists[0];
    }
};

class Solution {
    public boolean validSquare(int[] p1, int[] p2, int[] p3, int[] p4) {
        int[][] pts = {p1, p2, p3, p4};
        int[] dists = new int[6];
        int idx = 0;
        for (int i = 0; i < 4; i++) {
            for (int j = i + 1; j < 4; j++) {
                dists[idx++] = (pts[i][0] - pts[j][0]) * (pts[i][0] - pts[j][0]) +
                               (pts[i][1] - pts[j][1]) * (pts[i][1] - pts[j][1]);
            }
        }
        Arrays.sort(dists);
        return dists[0] > 0 &&
               dists[0] == dists[1] && dists[1] == dists[2] && dists[2] == dists[3] &&
               dists[4] == dists[5] && dists[4] == 2 * dists[0];
    }
}

var validSquare = function(p1, p2, p3, p4) {
    const pts = [p1, p2, p3, p4];
    const distSq = (a, b) => (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2;
    const dists = [];
    for (let i = 0; i < 4; i++) {
        for (let j = i + 1; j < 4; j++) {
            dists.push(distSq(pts[i], pts[j]));
        }
    }
    dists.sort((a, b) => a - b);
    return dists[0] > 0 &&
           dists[0] === dists[1] && dists[1] === dists[2] && dists[2] === dists[3] &&
           dists[4] === dists[5] && dists[4] === 2 * dists[0];
};
